/* Daily code breaker game. Needs cb-engine.js (window.CB) loaded first; the build prepends
 * CB_TABLE, the verified attempt index for each date and length, so the page skips straight to the
 * puzzle that passed the build's checks instead of retrying seeds on the phone. */
(function () {
  "use strict";
  var root = document.getElementById("cb");
  if (!root || !window.CB) return;
  var CB = window.CB;
  var TABLE = window.CB_TABLE || {};
  var LENGTHS = [3, 4, 5];
  var LABEL = { 3: "Easy", 4: "Medium", 5: "Hard" };

  function store(key, value) {
    try {
      if (value === undefined) return JSON.parse(localStorage.getItem(key) || "null");
      localStorage.setItem(key, JSON.stringify(value));
    } catch (e) {
      return null;
    }
  }

  function localIso(d) {
    return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
  }

  var today = localIso(new Date());
  var prettyDate = new Date().toLocaleDateString("en", { weekday: "long", day: "numeric", month: "long" });
  var el = function (sel) { return root.querySelector(sel); };

  var state = null;

  function puzzleFor(n) {
    var row = TABLE[today];
    return CB.daily(today, n, row ? row[LENGTHS.indexOf(n)] : null);
  }

  function savedKey() { return "cb:v1:" + state.date + ":" + state.n; }

  function start(n, puzzle, practice) {
    var solver = new CB.LogicSolver(n, puzzle.clues);
    var k = new CB.Knowledge(n);
    solver.applyGivens(k);
    state = {
      n: n, puzzle: puzzle, practice: practice, date: today, solver: solver, k: k,
      entry: new Array(n).fill(""), locked: new Array(n).fill(false), cursor: 0,
      attempts: 0, hints: 0, notes: new Array(10).fill(0), solved: false, started: Date.now(),
      revealOrder: revealOrder(puzzle, solver),
    };
    if (!practice) {
      var saved = store(savedKey());
      if (saved && saved.solved) {
        state.solved = true;
        state.attempts = saved.attempts;
        state.hints = saved.hints;
        state.entry = puzzle.code.split("");
        state.seconds = saved.seconds;
      }
    }
    render();
  }

  function revealOrder(puzzle, solver) {
    var full = solver.solve();
    var fix = new Array(puzzle.length).fill(1e9);
    var k = new CB.Knowledge(puzzle.length);
    full.steps.forEach(function (s, i) {
      s.facts.forEach(function (f) { k.apply(f); });
      for (var p = 0; p < puzzle.length; p++) if (fix[p] === 1e9 && k.digitAtSlot(p) >= 0) fix[p] = i;
    });
    return Object.keys(fix).map(Number).sort(function (a, b) { return fix[b] - fix[a] || a - b; });
  }

  function clueRow(c, i) {
    var tiles = c.guess.split("").map(function (d) { return '<span class="cb-tile">' + d + "</span>"; }).join("");
    var label = "Clue " + (i + 1) + ". Guess " + c.guess.split("").join(" ") + ". " + CB.clueText(c);
    return '<li class="cb-clue" aria-label="' + label + '"><span class="cb-num" aria-hidden="true">' + (i + 1) +
      '</span><span class="cb-guess" aria-hidden="true">' + tiles + '</span><span class="cb-text" aria-hidden="true">' +
      CB.clueText(c) + "</span></li>";
  }

  function render() {
    var s = state;
    LENGTHS.forEach(function (n) {
      var b = el('[data-len="' + n + '"]');
      b.setAttribute("aria-selected", String(n === s.n && !s.practice));
    });
    el(".cb-title").textContent = s.practice ? "Practice vault, " + s.n + " digits" : "Daily vault for " + prettyDate;
    el(".cb-back").hidden = !s.practice;
    el(".cb-clues").innerHTML = s.puzzle.clues.map(clueRow).join("");
    var slots = "";
    for (var i = 0; i < s.n; i++) {
      var cls = "cb-slot" + (i === s.cursor && !s.solved ? " is-cursor" : "") + (s.locked[i] ? " is-locked" : "");
      slots += '<button type="button" class="' + cls + '" data-slot="' + i + '" aria-label="Slot ' + (i + 1) + (s.entry[i] ? ", " + s.entry[i] : ", empty") + '">' + (s.entry[i] || "") + "</button>";
    }
    el(".cb-slots").innerHTML = slots;
    var used = s.entry.join("");
    root.querySelectorAll("[data-key]").forEach(function (b) {
      b.disabled = s.solved || used.indexOf(b.getAttribute("data-key")) >= 0;
    });
    el("[data-del]").disabled = s.solved;
    el("[data-open]").disabled = s.solved || s.entry.some(function (d) { return !d; });
    root.querySelectorAll("[data-note]").forEach(function (b) {
      var v = s.notes[Number(b.getAttribute("data-note"))];
      b.className = "cb-note" + (v === 1 ? " is-out" : v === 2 ? " is-in" : "");
      b.setAttribute("aria-label", b.getAttribute("data-note") + (v === 1 ? ", ruled out" : v === 2 ? ", in the code" : ", unknown"));
    });
    el(".cb-stats").textContent = "Attempts " + s.attempts + "  ·  Hints " + s.hints;
    el("[data-hint-step]").disabled = s.solved;
    el("[data-hint-reveal]").disabled = s.solved || s.locked.every(Boolean);
    var done = el(".cb-solved");
    done.hidden = !s.solved;
    if (s.solved) {
      el(".cb-solved-code").textContent = s.puzzle.code;
      el(".cb-solved-line").textContent = summary();
      el("[data-share]").hidden = s.practice;
    }
    root.setAttribute("data-ready", "1");
  }

  function summary() {
    var s = state;
    var t = s.seconds || 0;
    var time = Math.floor(t / 60) + ":" + String(t % 60).padStart(2, "0");
    return "Opened in " + s.attempts + (s.attempts === 1 ? " attempt" : " attempts") + " with " +
      (s.hints === 0 ? "no hints" : s.hints === 1 ? "1 hint" : s.hints + " hints") + ", time " + time + ".";
  }

  function say(text, tone) {
    var m = el(".cb-msg");
    m.textContent = text;
    m.className = "cb-msg" + (tone ? " is-" + tone : "");
  }

  function moveCursor(from) {
    for (var step = 1; step <= state.n; step++) {
      var i = (from + step) % state.n;
      if (!state.locked[i] && !state.entry[i]) {
        state.cursor = i;
        return;
      }
    }
  }

  function typeDigit(d) {
    var s = state;
    if (s.solved || s.entry.indexOf(d) >= 0) return;
    if (s.locked[s.cursor]) moveCursor(s.cursor);
    if (s.locked[s.cursor]) return;
    s.entry[s.cursor] = d;
    moveCursor(s.cursor);
    say("");
    render();
  }

  function erase() {
    var s = state;
    if (s.solved) return;
    if (!s.entry[s.cursor] || s.locked[s.cursor]) {
      for (var i = s.cursor - 1; i >= 0; i--) {
        if (s.entry[i] && !s.locked[i]) {
          s.cursor = i;
          break;
        }
      }
    }
    if (!s.locked[s.cursor]) s.entry[s.cursor] = "";
    render();
  }

  function open() {
    var s = state;
    if (s.solved || s.entry.some(function (d) { return !d; })) return;
    var code = s.entry.join("");
    s.attempts++;
    if (code === s.puzzle.code) {
      s.solved = true;
      s.seconds = Math.round((Date.now() - s.started) / 1000);
      say("");
      if (!s.practice) {
        store(savedKey(), { solved: true, attempts: s.attempts, hints: s.hints, seconds: s.seconds });
        bumpStreak();
      }
      render();
      el(".cb-solved").focus();
      return;
    }
    var broken = [];
    s.puzzle.clues.forEach(function (c, i) {
      var fb = CB.evaluate(code, c.guess);
      if (fb.exact !== c.exact || fb.total !== c.total) broken.push(i + 1);
    });
    var list = broken.length === 1 ? "clue " + broken[0] :
      "clues " + broken.slice(0, -1).join(", ") + " and " + broken[broken.length - 1];
    say(code + " isn't the combination. It breaks " + list + ". Check " +
      (broken.length === 1 ? "that clue" : "those clues") + " against your code and try again.", "bad");
    render();
  }

  function bumpStreak() {
    var key = "cb:streak:" + state.n;
    var st = store(key) || { last: "", count: 0, best: 0 };
    if (st.last === today) return;
    var y = new Date();
    y.setDate(y.getDate() - 1);
    st.count = st.last === localIso(y) ? st.count + 1 : 1;
    st.best = Math.max(st.best, st.count);
    st.last = today;
    store(key, st);
  }

  function hintStep() {
    var s = state;
    if (s.solved) return;
    var step = s.solver.next(s.k, true, true);
    if (!step) {
      say("The clues and your hints already pin down the code. Fill it in and open the vault.", "info");
      return;
    }
    step.facts.forEach(function (f) { s.k.apply(f); });
    s.hints++;
    say("Hint: " + CB.explain(step, s.n), "info");
    render();
  }

  function hintReveal() {
    var s = state;
    if (s.solved) return;
    var slot = s.revealOrder.filter(function (p) { return !s.locked[p]; })[0];
    if (slot === undefined) return;
    var d = s.puzzle.code.charAt(slot);
    var clash = s.entry.indexOf(d);
    if (clash >= 0 && clash !== slot) s.entry[clash] = "";
    s.entry[slot] = d;
    s.locked[slot] = true;
    s.k.apply({ t: "at", d: Number(d), p: slot });
    s.hints++;
    if (s.cursor === slot) moveCursor(slot);
    say("Hint: slot " + (slot + 1) + " (from the left) is " + d + ".", "info");
    render();
  }

  function share() {
    var text = "I cracked today's " + state.n + " digit vault on ManextApps. " + summary() + " " + location.origin + location.pathname;
    if (navigator.share) {
      navigator.share({ text: text }).catch(function () {});
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(text).then(function () { say("Result copied. The code is not in it, so no spoilers.", "ok"); });
    }
  }

  function practice() {
    var n = state.n;
    var seed = (Math.random() * 4294967296) >>> 0;
    if (window.crypto && crypto.getRandomValues) seed = crypto.getRandomValues(new Uint32Array(1))[0];
    say("Building a practice vault…", "info");
    var nextSeed = new CB.Rng(seed);
    var spec = CB.SPECS[CB.DAILY_TIERS[n]];
    (function attempt(i) {
      var p = CB.generate(nextSeed.next(), spec);
      if (p) {
        say("");
        start(n, p, true);
        return;
      }
      if (i < 600) setTimeout(function () { attempt(i + 1); }, 0);
      else say("That took too long. Try again.", "bad");
    })(0);
  }

  root.addEventListener("click", function (e) {
    var t = e.target.closest("button");
    if (!t || !root.contains(t)) return;
    if (t.hasAttribute("data-len")) {
      var n = Number(t.getAttribute("data-len"));
      store("cb:len", n);
      say("");
      start(n, puzzleFor(n), false);
    } else if (t.hasAttribute("data-key")) typeDigit(t.getAttribute("data-key"));
    else if (t.hasAttribute("data-slot")) {
      state.cursor = Number(t.getAttribute("data-slot"));
      render();
    } else if (t.hasAttribute("data-del")) erase();
    else if (t.hasAttribute("data-open")) open();
    else if (t.hasAttribute("data-note")) {
      var d = Number(t.getAttribute("data-note"));
      state.notes[d] = (state.notes[d] + 1) % 3;
      render();
    } else if (t.hasAttribute("data-hint-step")) hintStep();
    else if (t.hasAttribute("data-hint-reveal")) hintReveal();
    else if (t.hasAttribute("data-share")) share();
    else if (t.hasAttribute("data-practice")) practice();
    else if (t.hasAttribute("data-back")) {
      say("");
      start(state.n, puzzleFor(state.n), false);
    }
  });

  document.addEventListener("keydown", function (e) {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    var tag = (e.target.tagName || "").toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select") return;
    if (!root.contains(document.activeElement) && document.activeElement !== document.body) return;
    if (/^[0-9]$/.test(e.key)) {
      typeDigit(e.key);
      e.preventDefault();
    } else if (e.key === "Backspace") {
      erase();
      e.preventDefault();
    } else if (e.key === "Enter" && state && !state.solved && state.entry.every(Boolean)) {
      open();
      e.preventDefault();
    } else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      state.cursor = (state.cursor + (e.key === "ArrowLeft" ? state.n - 1 : 1)) % state.n;
      render();
    }
  });

  var first = store("cb:len");
  var n0 = LENGTHS.indexOf(first) >= 0 ? first : 4;
  start(n0, puzzleFor(n0), false);
})();
